<x-app-layout><div class="mx-auto max-w-5xl space-y-5 p-4 sm:p-6"><div><h1 class="text-2xl font-bold">Board Question Solver</h1><p class="text-gray-600">Prepare for SSC, HSC and board examinations with step-by-step explanations in Bangla or English.</p></div><div class="rounded-xl border bg-white p-4 sm:p-6"><form id="board-solver-form" enctype="multipart/form-data" class="space-y-4">@csrf<div class="grid gap-3 sm:grid-cols-2"><label class="block text-sm">Education Board<select name="board" class="mt-1 w-full rounded border p-2"><option value="">Not specified</option>@foreach(['Dhaka','Chattogram','Rajshahi','Cumilla','Jashore','Barishal','Sylhet','Dinajpur','Mymensingh','Madrasah','Technical'] as $board)<option>{{ $board }}</option>@endforeach</select></label><label class="block text-sm">Exam year<input type="number" name="exam_year" min="1990" max="{{ now()->year+1 }}" placeholder="{{ now()->year }}" class="mt-1 w-full rounded border p-2"></label><label class="block text-sm">Class / Level<select name="class_level" class="mt-1 w-full rounded border p-2"><option value="">Select</option>@foreach(['Class 6','Class 7','Class 8','Class 9','SSC','HSC','Alim','Dakhil','Vocational','Other'] as $level)<option>{{ $level }}</option>@endforeach</select></label><label class="block text-sm">Subject<input required name="subject" maxlength="100" placeholder="English, Bangla, Mathematics…" class="mt-1 w-full rounded border p-2"></label><label class="block text-sm">Question type<select name="question_type" class="mt-1 w-full rounded border p-2"><option value="creative">Creative / CQ</option><option value="mcq">MCQ</option><option value="short">Short question</option><option value="grammar">Grammar / Writing</option><option value="math">Mathematics</option><option value="science">Science</option><option value="other">Other</option></select></label><label class="block text-sm">Answer language<select name="language" class="mt-1 w-full rounded border p-2"><option value="bn" @selected($settings['default_language']==='bn')>বাংলা</option><option value="en" @selected($settings['default_language']==='en')>English</option></select></label></div><label class="block text-sm">Write / paste the question<textarea name="question" rows="5" maxlength="{{ $settings['max_question_length'] }}" placeholder="এখানে প্রশ্ন লিখুন…" class="mt-1 w-full rounded border p-3"></textarea></label>@if($settings['allow_image_questions'])<label class="block text-sm">Or upload a clear question photo (JPG, PNG, WebP; max {{ number_format($settings['max_image_kb']/1024,1) }} MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp" class="mt-2 block w-full text-sm"></label>@endif<label class="block text-sm">Solution mode<select name="mode" class="mt-1 w-full rounded border p-2"><option value="full">Full step-by-step solution</option><option value="hints">Hints first (practice mode)</option><option value="explain">Explain the concept</option></select></label><button id="board-solver-submit" class="rounded-lg bg-blue-700 px-5 py-3 font-semibold text-white">Solve Question</button></form><p id="board-solver-status" class="mt-3 text-sm" aria-live="polite"></p></div><section id="board-solver-answer" class="hidden rounded-xl border bg-white p-4 sm:p-6"><h2 class="text-xl font-bold">Solution</h2><div id="board-solver-answer-text" class="mt-3 whitespace-pre-wrap text-sm leading-8"></div></section><div class="flex flex-wrap gap-4"><a class="text-blue-700 underline" href="{{ route('student.board-solver.history') }}">My solved questions</a></div></div>
<script>
(()=>{const form=document.getElementById('board-solver-form'),button=document.getElementById('board-solver-submit'),status=document.getElementById('board-solver-status'),answer=document.getElementById('board-solver-answer'),text=document.getElementById('board-solver-answer-text');form.addEventListener('submit',async e=>{e.preventDefault();button.disabled=true;button.textContent='Solving…';status.textContent='Your question is being analysed. Please wait.';answer.classList.add('hidden');try{const response=await fetch(@json(route('student.board-solver.solve')),{method:'POST',body:new FormData(form),headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});const data=await response.json();if(!response.ok)throw new Error(data.message||'Unable to solve this question.');text.textContent=data.solution;answer.classList.remove('hidden');status.textContent='Solution ready. Review the steps and practise on your own.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;button.textContent='Solve Question';}});})();
</script></x-app-layout>